mapper.insert:
INSERT INTO its_application_data (cmdb_id, application_name, description, application_it_owner, operation_owner, app_status, certification_status, cmdb_update_time, cmdb_active_time, sync_batch_id, operation_owner_domain, operation_owner_tower,sensitive_app, create_by, create_time, update_by, update_time, delete_flag ) VALUES
(#{r.cmdbId}, #{r.applicationName}, #{r.description}, #{r.applicationItOwner}, #{r.operationOwner}, #{r.appStatus}, #{r.certificationStatus}, #{r.cmdbUpdateTime}, #{r.cmdbActiveTime}, #{syncBatchId}, #{r.operationOwnerDomain}, #{r.operationOwnerTower}, #{r.sensitiveApp}, 'JOB', CURRENT_TIMESTAMP, 'JOB', CURRENT_TIMESTAMP, false )
ON CONFLICT (cmdb_id) DO UPDATE SET application_name = EXCLUDED.application_name, description = EXCLUDED.description, application_it_owner = EXCLUDED.application_it_owner, operation_owner = EXCLUDED.operation_owner, app_status = EXCLUDED.app_status, certification_status = EXCLUDED.certification_status, cmdb_update_time = EXCLUDED.cmdb_update_time, cmdb_active_time = EXCLUDED.cmdb_active_time, sync_batch_id = EXCLUDED.sync_batch_id, operation_owner_domain = EXCLUDED.operation_owner_domain, operation_owner_tower = EXCLUDED.operation_owner_tower, sensitive_app = EXCLUDED.sensitive_app, update_by = EXCLUDED.update_by, update_time = EXCLUDED.update_time, delete_flag = false ;

mapper.update:
UPDATE its_application_data
SET delete_flag = true, update_time = CURRENT_TIMESTAMP, update_by = 'JOB'
WHERE sync_batch_id != #{syncBatchId}

